H.background();
const w = H.W, hh = H.H;
const a = Math.round(P.a), b = Math.round(P.b), c = Math.round(P.c);
// PEMDAS worked example: a + b * c  vs  (a + b) * c
const step = Math.floor((t % 6) / 2); // 0,1,2 stepped reveal
H.text("Order of operations:  a + b × c", 24, 32, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Multiply BEFORE you add — grouping changes the answer.", 24, 54, { color: H.colors.sub, size: 13 });
// Left column: correct PEMDAS path
const bx = 60, by = 120, rowH = 56;
H.text("a + b × c", bx, by, { color: H.colors.ink, size: 20, weight: 700 });
if (step >= 1) {
  H.text("= a + (" + b + " × " + c + ")", bx, by + rowH, { color: H.colors.accent, size: 18 });
  H.rect(bx + 38, by + rowH - 22, 86, 30, { stroke: H.colors.warn, width: 2, radius: 6 });
}
if (step >= 2) {
  H.text("= " + a + " + " + (b * c), bx, by + rowH * 2, { color: H.colors.accent, size: 18 });
  H.text("= " + (a + b * c), bx, by + rowH * 3, { color: H.colors.good, size: 22, weight: 700 });
}
// Right column: the WRONG left-to-right path, for contrast
const rx = w * 0.56;
H.text("(forcing left-to-right is WRONG)", rx, by - 26, { color: H.colors.sub, size: 12 });
H.text("a + b × c", rx, by, { color: H.colors.ink, size: 20, weight: 700 });
const wrongVal = (a + b) * c;
const rel = (a + b * c) === wrongVal ? "= " : "≠ ";
H.text(rel + "(" + a + " + " + b + ") × " + c + " = " + wrongVal, rx, by + rowH, { color: H.colors.warn, size: 18 });
// animated pointer that sweeps to the operation done first
const px = bx + 70 + 8 * Math.sin(t * 3);
H.circle(px, by + rowH + 4 + (step >= 1 ? 0 : 30), 6, { fill: H.colors.warn });
